    suspend fun getRandomAlbums(size: Int = 50): Result<List<Album>> {
        return cacheManager.getAlbums(
            key = "random_albums_$size",
            type = CacheTypes.ALBUM_LIST_TYPE
        ) {
            try {
                val (username, token, salt) = getAuthParams()
                // Obtener canciones aleatorias para extraer álbumes únicos
                val response = NavidromeClient.getApiService().getRandomSongs(
                    username = username,
                    token = token,
                    salt = salt,
                    version = "1.16.1",
                    client = "Castafiore",
                    size = size
                )

                if (response.isSuccessful) {
                    response.body()?.let { randomSongsResponse ->
                        val songs = randomSongsResponse.subsonicResponse.randomSongs?.song ?: emptyList()

                        // Extraer álbumes únicos de las canciones aleatorias
                        val uniqueAlbums = songs
                            .mapNotNull { song ->
                                // Crear objeto Album basado en la información de la canción
                                if (song.albumId != null && song.album != null) {
                                    Album(
                                        id = song.albumId!!,
                                        name = song.album!!,
                                        artist = song.artist ?: "Artista Desconocido",
                                        artistId = song.artistId ?: "",
                                        coverArt = song.coverArt,
                                        songCount = 0, // No tenemos esta información desde las canciones
                                        duration = 0, // No tenemos esta información desde las canciones
                                        created = "", // Esta propiedad no existe en Song
                                        year = song.year,
                                        genre = song.genre
                                    )
                                } else null
                            }
                            .distinctBy { it.id } // Eliminar álbumes duplicados
                            .shuffled() // Mezclar para mayor aleatoriedad

                        Result.success(uniqueAlbums)
                    } ?: Result.failure(Exception("Empty response"))
                } else {
                    Result.failure(Exception("HTTP Error: ${response.code()} - ${response.message()}"))
                }
            } catch (e: Exception) {
                Result.failure(e)
            }
        }
    }

    suspend fun getSimilarSongs(baseSongId: String, size: Int = 15): Result<List<Song>> {
        return try {
            val (username, token, salt) = getAuthParams()
            val response = NavidromeClient.getApiService().getSimilarSongs(
                username = username,
                token = token,
                salt = salt,
                version = "1.16.1",
                client = "Castafiore",
                id = baseSongId,
                size = size
            )

            if (response.isSuccessful) {
                response.body()?.let { similarResponse ->
                    val songs = similarResponse.subsonicResponse.similarSongs?.song ?: emptyList()
                    Result.success(songs)
                } ?: Result.failure(Exception("Empty response"))
            } else {
                Result.failure(Exception("HTTP Error: ${response.code()} - ${response.message()}"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}

package com.arantec.castafiore.service

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.media.session.MediaButtonReceiver
import androidx.core.content.ContextCompat
import androidx.media.app.NotificationCompat.MediaStyle
import android.support.v4.media.MediaMetadataCompat
import android.app.Service
import android.os.Binder
import android.os.IBinder
import android.support.v4.media.session.MediaSessionCompat
import android.support.v4.media.session.PlaybackStateCompat
import com.arantec.castafiore.R
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.utils.ImageLoader
import com.google.android.exoplayer2.ExoPlayer
import com.google.android.exoplayer2.MediaItem
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import android.content.pm.ServiceInfo
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import com.arantec.castafiore.ui.activities.PlayerActivity

class MusicService : Service() {

    private lateinit var mediaSession: MediaSessionCompat
    private lateinit var musicRepository: MusicRepository
    private val binder = MusicBinder()
    private var exoPlayer: ExoPlayer? = null

    private var currentSong: Song? = null
    private var isPlaying = false
    private var currentPosition = 0L
    private var playlist = mutableListOf<Song>()
    private var currentIndex = 0
    private var repeatMode = RepeatMode.OFF
    private var originalQueue: MutableList<Song>? = null
    private var progressJob: Job? = null

    // Enum para los modos de repetición
    enum class RepeatMode {
        OFF, ALL, ONE
    }

    // Listeners para cambios de estado
    private val playbackStateListeners = mutableListOf<(Boolean) -> Unit>()
    private val songChangeListeners = mutableListOf<(Song?) -> Unit>()

    companion object {
        private const val TAG = "MusicService"
        private const val MEDIA_SESSION_TAG = "CastafioreMediaSession"
        private const val NOTIFICATION_CHANNEL_ID = "playback_channel"
        private const val NOTIFICATION_ID = 2001
    }

    inner class MusicBinder : Binder() {
        fun getService(): MusicService = this@MusicService
    }

    override fun onCreate() {
        super.onCreate()

        musicRepository = MusicRepository.getInstance(this)

        createNotificationChannel()

        // Inicializar MediaSession
        mediaSession = MediaSessionCompat(this, MEDIA_SESSION_TAG).apply {
            setFlags(
                MediaSessionCompat.FLAG_HANDLES_MEDIA_BUTTONS or
                MediaSessionCompat.FLAG_HANDLES_TRANSPORT_CONTROLS
            )
            setCallback(mediaSessionCallback)
            isActive = true
        }

        exoPlayer = ExoPlayer.Builder(this).build()
        exoPlayer?.addListener(object : com.google.android.exoplayer2.Player.Listener {
            override fun onPlaybackStateChanged(state: Int) {
                if (state == com.google.android.exoplayer2.Player.STATE_ENDED) {
                    when (repeatMode) {
                        RepeatMode.ONE -> {
                            // Repetir la canción actual
                            startNewSong()
                        }
                        RepeatMode.ALL -> {
                            // Si hay más canciones, avanzar; si no, volver al inicio
                            if (currentIndex < playlist.size - 1) {
                                next()
                            } else if (playlist.isNotEmpty()) {
                                // Volver al inicio de la lista
                                currentIndex = 0
                                currentSong = playlist[currentIndex]
                                notifySongChanged(currentSong)
                                startNewSong()
                            }
                        }
                        RepeatMode.OFF -> {
                            // Si hay más canciones, avanzar; si no, continuar con similares
                            if (currentIndex < playlist.size - 1) {
                                next()
                            } else {
                                // Fin de la cola: intentar continuar con canciones similares
                                continueWithSimilarSongs()
                            }
                        }
                    }
                }
                // Actualizar notificación cuando ExoPlayer cambia a READY o BUFFERING
                showOrUpdateNotification()
            }
            override fun onMediaItemTransition(mediaItem: MediaItem?, reason: Int) {
                // Actualizar el mini player al cambiar de canción
                currentSong = playlist.getOrNull(currentIndex)
                updateMediaMetadata()
                notifySongChanged(currentSong)
                showOrUpdateNotification()
            }
        })

        updatePlaybackState()
        updateMediaMetadata()
    }

    override fun onBind(intent: Intent): IBinder {
        return binder
    }

    override fun onDestroy() {
        exoPlayer?.release()
        exoPlayer = null
        mediaSession.release()
        playbackStateListeners.clear()
        songChangeListeners.clear()
        stopProgressUpdates()
        super.onDestroy()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        MediaButtonReceiver.handleIntent(mediaSession, intent)
        return START_NOT_STICKY
    }

    private val mediaSessionCallback = object : MediaSessionCompat.Callback() {
        override fun onPlay() {
            play()
        }

        override fun onPause() {
            pause()
        }

        override fun onStop() {
            stop()
        }

        override fun onSkipToNext() {
            next()
        }

        override fun onSkipToPrevious() {
            previous()
        }

        override fun onSeekTo(pos: Long) {
            seekTo(pos)
        }
    }

    // Métodos públicos para controlar la reproducción
    fun play() {
        // Solo reanudar si ya hay una canción preparada
        if (exoPlayer?.playbackState == com.google.android.exoplayer2.Player.STATE_READY) {
            // El reproductor ya está preparado, solo reanudar
            exoPlayer?.play()
        } else {
            // Preparar y reproducir nueva canción
            startNewSong()
        }

        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
        showOrUpdateNotification()
        startProgressUpdates()
    }

    private fun startNewSong() {
        val song = currentSong ?: return
        val serverUrl = musicRepository.serverUrl ?: return
        val (username, token, salt) = musicRepository.getAuthParams()
        val streamUrl = song.getStreamUrl(serverUrl, username, token, salt)
        val mediaItem = MediaItem.fromUri(streamUrl)
        exoPlayer?.setMediaItem(mediaItem)
        exoPlayer?.prepare()
        exoPlayer?.play()
        updateMediaMetadata()
        showOrUpdateNotification()
        startProgressUpdates()
    }

    fun resume() {
        // Método específico para reanudar sin reiniciar
        if (exoPlayer?.playbackState == com.google.android.exoplayer2.Player.STATE_READY) {
            exoPlayer?.play()
            isPlaying = true
            updatePlaybackState()
            notifyPlaybackStateChanged(true)
            showOrUpdateNotification()
            startProgressUpdates()
        } else {
            // Si no está listo, llamar a play normal
            play()
        }
    }

    fun pause() {
        isPlaying = false
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        exoPlayer?.pause()
        showOrUpdateNotification()
        stopProgressUpdates()
    }

    fun stop() {
        isPlaying = false
        currentPosition = 0L
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        exoPlayer?.stop()
        stopForeground(true)
        (getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager).cancel(NOTIFICATION_ID)
        stopSelf()
        stopProgressUpdates()
    }

    fun togglePlayPause() {
        if (isPlaying) {
            pause()
        } else {
            play()
        }
    }

    fun next() {
        if (currentIndex < playlist.size - 1) {
            currentIndex++
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)

            // Usar startNewSong para preparar correctamente la nueva canción
            startNewSong()
            if (isPlaying) {
                updatePlaybackState()
                notifyPlaybackStateChanged(true)
                showOrUpdateNotification()
            }
        }
    }

    fun previous() {
        if (currentIndex > 0) {
            currentIndex--
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)

            // Usar startNewSong para preparar correctamente la nueva canción
            startNewSong()
            if (isPlaying) {
                updatePlaybackState()
                notifyPlaybackStateChanged(true)
                showOrUpdateNotification()
            }
        }
    }

    fun seekTo(position: Long) {
        currentPosition = position
        updatePlaybackState()
        exoPlayer?.seekTo(position)
    }

    fun playQueue(songs: List<Song>, startIndex: Int = 0) {
        playlist.clear()
        playlist.addAll(songs)
        currentIndex = startIndex
        currentSong = if (songs.isNotEmpty()) songs[startIndex] else null
        notifySongChanged(currentSong)
        notifyQueueChanged(playlist.toList())

        // Usar startNewSong para asegurar que se prepare correctamente
        startNewSong()
        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
        showOrUpdateNotification()
    }

    fun playSong(song: Song) {
        playlist.clear()
        playlist.add(song)
        currentIndex = 0
        currentSong = song
        notifySongChanged(currentSong)
        notifyQueueChanged(playlist.toList())

        // Usar startNewSong para asegurar que se prepare correctamente
        startNewSong()
        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
        showOrUpdateNotification()
    }

    // --- Notificación y metadata ---
    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                NOTIFICATION_CHANNEL_ID,
                getString(R.string.app_name),
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Reproducción de música"
                setSound(null, null)
                enableVibration(false)
            }
            val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            nm.createNotificationChannel(channel)
        }
    }

    private fun getContentPendingIntent(): PendingIntent? {
        // Abrir directamente PlayerActivity al tocar la notificación
        val intent = Intent(this, PlayerActivity::class.java).apply {
            addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)
        }
        return PendingIntent.getActivity(
            this,
            0,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
    }

    private fun buildBaseNotification(largeIcon: Bitmap? = null): NotificationCompat.Builder {
        val song = currentSong
        val title = song?.title ?: getString(R.string.app_name)
        val artist = song?.artist ?: ""

        val playPauseAction = NotificationCompat.Action(
            if (isPlaying) R.drawable.ic_pause else R.drawable.ic_play,
            if (isPlaying) getString(R.string.pause) else getString(R.string.play),
            MediaButtonReceiver.buildMediaButtonPendingIntent(
                this,
                PlaybackStateCompat.ACTION_PLAY_PAUSE
            )
        )
        val prevAction = NotificationCompat.Action(
            R.drawable.ic_arrow_back,
            getString(R.string.previous),
            MediaButtonReceiver.buildMediaButtonPendingIntent(
                this,
                PlaybackStateCompat.ACTION_SKIP_TO_PREVIOUS
            )
        )
        val nextAction = NotificationCompat.Action(
            R.drawable.ic_skip_next,
            getString(R.string.next),
            MediaButtonReceiver.buildMediaButtonPendingIntent(
                this,
                PlaybackStateCompat.ACTION_SKIP_TO_NEXT
            )
        )

        val style = MediaStyle()
            .setMediaSession(mediaSession.sessionToken)
            .setShowActionsInCompactView(0, 1, 2)

        val builder = NotificationCompat.Builder(this, NOTIFICATION_CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_music_note)
            .setContentTitle(title)
            .setContentText(artist)
            .setContentIntent(getContentPendingIntent())
            .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
            .setCategory(Notification.CATEGORY_TRANSPORT)
            .setOnlyAlertOnce(true)
            .setColor(ContextCompat.getColor(this, R.color.primary))
            .setStyle(style)
            .addAction(prevAction)
            .addAction(playPauseAction)
            .addAction(nextAction)

        if (largeIcon != null) builder.setLargeIcon(largeIcon)

        return builder
    }

    private fun showOrUpdateNotification() {
        val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        val isForeground = isPlaying

        // Cargar carátula en background y actualizar notificación
        val song = currentSong
        if (song != null && musicRepository.serverUrl != null) {
            val (u, t, s) = musicRepository.getAuthParams()
            val coverUrl = song.getCoverArtUrl(musicRepository.serverUrl!!, u, t, s)
            CoroutineScope(Dispatchers.IO).launch {
                val bitmap = try {
                    if (coverUrl != null) {
                        val future = com.bumptech.glide.Glide.with(this@MusicService)
                            .asBitmap()
                            .load(coverUrl)
                            .submit(256, 256)
                        future.get()
                    } else null
                } catch (_: Exception) { null }

                withContext(Dispatchers.Main) {
                    val notification = buildBaseNotification(bitmap).build()
                    if (isForeground) {
                        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                            startForeground(NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK)
                        } else {
                            startForeground(NOTIFICATION_ID, notification)
                        }
                    } else {
                        nm.notify(NOTIFICATION_ID, notification)
                        // Mantener notificación visible pero quitar foreground si está pausado
                        stopForeground(false)
                    }
                }
            }
        } else {
            val notification = buildBaseNotification(null).build()
            if (isForeground) {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                    startForeground(NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK)
                } else {
                    startForeground(NOTIFICATION_ID, notification)
                }
            } else {
                nm.notify(NOTIFICATION_ID, notification)
                stopForeground(false)
            }
        }
    }

    private fun updateMediaMetadata() {
        val song = currentSong ?: return
        val metadata = MediaMetadataCompat.Builder()
            .putString(MediaMetadataCompat.METADATA_KEY_TITLE, song.title)
            .putString(MediaMetadataCompat.METADATA_KEY_ARTIST, song.artist)
            .putString(MediaMetadataCompat.METADATA_KEY_ALBUM, song.album)
            .putLong(MediaMetadataCompat.METADATA_KEY_DURATION, (song.duration * 1000).toLong())
            .build()
        mediaSession.setMetadata(metadata)
    }

    // Getters para el estado actual
    fun getCurrentSong(): Song? = currentSong
    fun isPlaying(): Boolean = isPlaying
    fun getCurrentPosition(): Long = exoPlayer?.currentPosition ?: 0L
    fun getDuration(): Long = exoPlayer?.duration ?: 0L
    fun getQueue(): List<Song> = playlist.toList()
    fun getCurrentIndex(): Int = currentIndex

    // Métodos públicos para registrar listeners (compatibilidad con ArtistDetailFragment)
    fun setOnSongChangeListener(listener: ((Song?) -> Unit)?) {
        songChangeListeners.clear()
        listener?.let { songChangeListeners.add(it) }
    }

    fun setOnPlaybackStateChangeListener(listener: ((Boolean) -> Unit)?) {
        playbackStateListeners.clear()
        listener?.let { playbackStateListeners.add(it) }
    }

    // Listeners para cambios de estado
    private val queueChangeListeners = mutableListOf<(List<Song>) -> Unit>()

    fun addPlaybackStateListener(listener: (Boolean) -> Unit) {
        playbackStateListeners.add(listener)
    }

    fun addSongChangeListener(listener: (Song?) -> Unit) {
        songChangeListeners.add(listener)
    }

    fun addQueueChangeListener(listener: (List<Song>) -> Unit) {
        queueChangeListeners.add(listener)
    }

    fun removePlaybackStateListener(listener: (Boolean) -> Unit) {
        playbackStateListeners.remove(listener)
    }

    fun removeSongChangeListener(listener: (Song?) -> Unit) {
        songChangeListeners.remove(listener)
    }

    fun removeQueueChangeListener(listener: (List<Song>) -> Unit) {
        queueChangeListeners.remove(listener)
    }

    private fun notifyPlaybackStateChanged(isPlaying: Boolean) {
        playbackStateListeners.forEach { it(isPlaying) }
    }

    private fun notifySongChanged(song: Song?) {
        songChangeListeners.forEach { it(song) }
    }

    private fun notifyQueueChanged(queue: List<Song>) {
        queueChangeListeners.forEach { it(queue) }
    }

    private fun updatePlaybackState() {
        val position = exoPlayer?.currentPosition ?: currentPosition
        currentPosition = position
        val buffered = exoPlayer?.bufferedPosition ?: 0L
        val state = if (isPlaying) PlaybackStateCompat.STATE_PLAYING else PlaybackStateCompat.STATE_PAUSED
        val speed = if (isPlaying) 1.0f else 0.0f

        val playbackState = PlaybackStateCompat.Builder()
            .setState(state, position, speed)
            .setBufferedPosition(buffered)
            .setActions(
                PlaybackStateCompat.ACTION_PLAY_PAUSE or
                PlaybackStateCompat.ACTION_SKIP_TO_NEXT or
                PlaybackStateCompat.ACTION_SKIP_TO_PREVIOUS or
                PlaybackStateCompat.ACTION_SEEK_TO
            )
            .build()

        mediaSession.setPlaybackState(playbackState)
    }

    fun addToQueue(song: Song) {
        playlist.add(song)
        notifyQueueChanged(playlist.toList())
    }

    fun playNext(song: Song) {
        val insertPosition = currentIndex + 1
        if (insertPosition <= playlist.size) {
            playlist.add(insertPosition, song)
            notifyQueueChanged(playlist.toList())
        } else {
            addToQueue(song)
        }
    }

    fun shuffleQueue() {
        if (playlist.isEmpty()) return
        // Guardar orden original una sola vez
        if (originalQueue == null) {
            originalQueue = playlist.toMutableList()
        }
        val played = playlist.take(currentIndex + 1)
        val remaining = playlist.drop(currentIndex + 1).shuffled()
        playlist.clear()
        playlist.addAll(played + remaining)
        notifyQueueChanged(playlist.toList())
    }

    fun unshuffleQueue() {
        val original = originalQueue ?: return
        // Mantener la canción actual si existe
        val current = currentSong
        playlist.clear()
        playlist.addAll(original)
        originalQueue = null
        currentIndex = current?.let { song -> playlist.indexOfFirst { it.id == song.id } }.takeIf { it != null && it >= 0 } ?: 0
        currentSong = playlist.getOrNull(currentIndex)
        notifyQueueChanged(playlist.toList())
    }

    fun setRepeatMode(mode: RepeatMode) {
        repeatMode = mode
        // Mapear con ExoPlayer: solo repetir UNA pista a nivel ExoPlayer.
        // Para repetir TODA la cola, mantenemos REPEAT_MODE_OFF y dejamos que la lógica
        // de onPlaybackStateChanged avance por la playlist y regrese al inicio.
        val exoMode = when (mode) {
            RepeatMode.OFF -> com.google.android.exoplayer2.Player.REPEAT_MODE_OFF
            RepeatMode.ALL -> com.google.android.exoplayer2.Player.REPEAT_MODE_OFF
            RepeatMode.ONE -> com.google.android.exoplayer2.Player.REPEAT_MODE_ONE
        }
        exoPlayer?.repeatMode = exoMode
    }

    fun getRepeatMode(): RepeatMode = repeatMode

    fun playFromQueue(index: Int) {
        if (index in 0 until playlist.size) {
            currentIndex = index
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)
            startNewSong()
            isPlaying = true
            updatePlaybackState()
            notifyPlaybackStateChanged(true)
            showOrUpdateNotification()
        }
    }

    fun removeFromQueue(index: Int) {
        if (index in 0 until playlist.size) {
            playlist.removeAt(index)
            when {
                index < currentIndex -> currentIndex--
                index == currentIndex -> {
                    if (playlist.isNotEmpty()) {
                        if (currentIndex >= playlist.size) currentIndex = playlist.size - 1
                        currentSong = playlist[currentIndex]
                        notifySongChanged(currentSong)
                        startNewSong()
                    } else {
                        currentSong = null
                        notifySongChanged(null)
                        stop()
                    }
                }
            }
            notifyQueueChanged(playlist.toList())
        }
    }

    fun moveInQueue(fromIndex: Int, toIndex: Int) {
        if (fromIndex in 0 until playlist.size && toIndex in 0 until playlist.size) {
            val song = playlist.removeAt(fromIndex)
            playlist.add(toIndex, song)

            // Actualizar currentIndex si es necesario
            currentIndex = when {
                fromIndex == currentIndex -> toIndex
                fromIndex < currentIndex && toIndex >= currentIndex -> currentIndex - 1
                fromIndex > currentIndex && toIndex <= currentIndex -> currentIndex + 1
                else -> currentIndex
            }

            notifyQueueChanged(playlist.toList())
        }
    }

    // Inicia y detiene actualizaciones periódicas del progreso para la notificación/lockscreen
    private fun startProgressUpdates() {
        progressJob?.cancel()
        progressJob = CoroutineScope(Dispatchers.Main).launch {
            while (isPlaying) {
                updatePlaybackState()
                delay(1000L)
            }
        }
    }

    private fun stopProgressUpdates() {
        progressJob?.cancel()
        progressJob = null
    }

    private fun continueWithSimilarSongs() {
        val baseSong = currentSong
        if (baseSong == null) {
            stopAtEnd()
            return
        }
        CoroutineScope(Dispatchers.IO).launch {
            try {
                val similarResult = musicRepository.getSimilarSongs(baseSong.id, size = 25)
                val similar = similarResult.getOrNull()?.filter { it.id != baseSong.id } ?: emptyList()

                if (similar.isNotEmpty()) {
                    withContext(Dispatchers.Main) {
                        // Agregar al final de la cola y continuar
                        playlist.addAll(similar)
                        next()
                    }
                } else {
                    // Fallback a canciones aleatorias
                    val randomResult = musicRepository.getRandomSongs()
                    val randomSongs = randomResult.getOrNull() ?: emptyList()
                    if (randomSongs.isNotEmpty()) {
                        withContext(Dispatchers.Main) {
                            playlist.addAll(randomSongs)
                            next()
                        }
                    } else {
                        withContext(Dispatchers.Main) {
                            stopAtEnd()
                        }
                    }
                }
            } catch (_: Exception) {
                withContext(Dispatchers.Main) {
                    stopAtEnd()
                }
            }
        }
    }

    private fun stopAtEnd() {
        isPlaying = false
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        showOrUpdateNotification()
    }
}

package com.arantec.castafiore.service

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.media.session.MediaButtonReceiver
import androidx.core.content.ContextCompat
import androidx.media.app.NotificationCompat.MediaStyle
import android.support.v4.media.MediaMetadataCompat
import android.app.Service
import android.os.Binder
import android.os.IBinder
import android.support.v4.media.session.MediaSessionCompat
import android.support.v4.media.session.PlaybackStateCompat
import com.arantec.castafiore.R
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.utils.ImageLoader
import com.google.android.exoplayer2.ExoPlayer
import com.google.android.exoplayer2.MediaItem
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import android.content.pm.ServiceInfo
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import com.arantec.castafiore.ui.activities.PlayerActivity

class MusicService : Service() {

    private lateinit var mediaSession: MediaSessionCompat
    private lateinit var musicRepository: MusicRepository
    private val binder = MusicBinder()
    private var exoPlayer: ExoPlayer? = null

    private var currentSong: Song? = null
    private var isPlaying = false
    private var currentPosition = 0L
    private var playlist = mutableListOf<Song>()
    private var currentIndex = 0
    private var repeatMode = RepeatMode.OFF
    private var originalQueue: MutableList<Song>? = null
    private var progressJob: Job? = null
    private var prefetchedSimilar: List<Song>? = null

    // Enum para los modos de repetición
    enum class RepeatMode {
        OFF, ALL, ONE
    }

    // Listeners para cambios de estado
    private val playbackStateListeners = mutableListOf<(Boolean) -> Unit>()
    private val songChangeListeners = mutableListOf<(Song?) -> Unit>()

    companion object {
        private const val TAG = "MusicService"
        private const val MEDIA_SESSION_TAG = "CastafioreMediaSession"
        private const val NOTIFICATION_CHANNEL_ID = "playback_channel"
        private const val NOTIFICATION_ID = 2001
    }

    inner class MusicBinder : Binder() {
        fun getService(): MusicService = this@MusicService
    }

    override fun onCreate() {
        super.onCreate()

        musicRepository = MusicRepository.getInstance(this)

        createNotificationChannel()

        // Inicializar MediaSession
        mediaSession = MediaSessionCompat(this, MEDIA_SESSION_TAG).apply {
            setFlags(
                MediaSessionCompat.FLAG_HANDLES_MEDIA_BUTTONS or
                MediaSessionCompat.FLAG_HANDLES_TRANSPORT_CONTROLS
            )
            setCallback(mediaSessionCallback)
            isActive = true
        }

        exoPlayer = ExoPlayer.Builder(this).build()
        exoPlayer?.addListener(object : com.google.android.exoplayer2.Player.Listener {
            override fun onPlaybackStateChanged(state: Int) {
                if (state == com.google.android.exoplayer2.Player.STATE_ENDED) {
                    when (repeatMode) {
                        RepeatMode.ONE -> {
                            // Repetir la canción actual
                            startNewSong()
                        }
                        RepeatMode.ALL -> {
                            // Si hay más canciones, avanzar; si no, volver al inicio
                            if (currentIndex < playlist.size - 1) {
                                next()
                            } else if (playlist.isNotEmpty()) {
                                // Volver al inicio de la lista
                                currentIndex = 0
                                currentSong = playlist[currentIndex]
                                notifySongChanged(currentSong)
                                startNewSong()
                            }
                        }
                        RepeatMode.OFF -> {
                            if (currentIndex < playlist.size - 1) {
                                next()
                            } else {
                                // Usar prefetched primero para evitar espera
                                if (!prefetchedSimilar.isNullOrEmpty()) {
                                    val toAppend = prefetchedSimilar!!.filter { s -> playlist.none { it.id == s.id } }
                                    if (toAppend.isNotEmpty()) {
                                        playlist.addAll(toAppend)
                                        notifyQueueChanged(playlist.toList())
                                        prefetchedSimilar = null
                                        next()
                                        // Prefetch para la nueva canción en curso
                                        prefetchSimilarForCurrentSong()
                                        return
                                    }
                                }
                                // Fin de la cola: intentar continuar con canciones similares (con red)
                                continueWithSimilarSongs()
                            }
                        }
                    }
                }
                // Actualizar notificación cuando ExoPlayer cambia a READY o BUFFERING
                showOrUpdateNotification()
            }
            override fun onMediaItemTransition(mediaItem: MediaItem?, reason: Int) {
                // Actualizar el mini player al cambiar de canción
                currentSong = playlist.getOrNull(currentIndex)
                updateMediaMetadata()
                notifySongChanged(currentSong)
                showOrUpdateNotification()
                // Lanzar prefetch de similares de la canción actual (solo si repeat OFF)
                if (repeatMode == RepeatMode.OFF) {
                    prefetchSimilarForCurrentSong()
                }
            }
        })

        updatePlaybackState()
        updateMediaMetadata()
    }

    override fun onBind(intent: Intent): IBinder {
        return binder
    }

    override fun onDestroy() {
        exoPlayer?.release()
        exoPlayer = null
        mediaSession.release()
        playbackStateListeners.clear()
        songChangeListeners.clear()
        stopProgressUpdates()
        super.onDestroy()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        MediaButtonReceiver.handleIntent(mediaSession, intent)
        return START_NOT_STICKY
    }

    private val mediaSessionCallback = object : MediaSessionCompat.Callback() {
        override fun onPlay() {
            play()
        }

        override fun onPause() {
            pause()
        }

        override fun onStop() {
            stop()
        }

        override fun onSkipToNext() {
            next()
        }

        override fun onSkipToPrevious() {
            previous()
        }

        override fun onSeekTo(pos: Long) {
            seekTo(pos)
        }
    }

    // Métodos públicos para controlar la reproducción
    fun play() {
        // Solo reanudar si ya hay una canción preparada
        if (exoPlayer?.playbackState == com.google.android.exoplayer2.Player.STATE_READY) {
            // El reproductor ya está preparado, solo reanudar
            exoPlayer?.play()
        } else {
            // Preparar y reproducir nueva canción
            startNewSong()
        }

        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
        showOrUpdateNotification()
        startProgressUpdates()
    }

    private fun startNewSong() {
        val song = currentSong ?: return
        val serverUrl = musicRepository.serverUrl ?: return
        val (username, token, salt) = musicRepository.getAuthParams()
        val streamUrl = song.getStreamUrl(serverUrl, username, token, salt)
        val mediaItem = MediaItem.fromUri(streamUrl)
        exoPlayer?.setMediaItem(mediaItem)
        exoPlayer?.prepare()
        exoPlayer?.play()
        updateMediaMetadata()
        showOrUpdateNotification()
        startProgressUpdates()
    }

    fun resume() {
        // Método específico para reanudar sin reiniciar
        if (exoPlayer?.playbackState == com.google.android.exoplayer2.Player.STATE_READY) {
            exoPlayer?.play()
            isPlaying = true
            updatePlaybackState()
            notifyPlaybackStateChanged(true)
            showOrUpdateNotification()
            startProgressUpdates()
        } else {
            // Si no está listo, llamar a play normal
            play()
        }
    }

    fun pause() {
        isPlaying = false
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        exoPlayer?.pause()
        showOrUpdateNotification()
        stopProgressUpdates()
    }

    fun stop() {
        isPlaying = false
        currentPosition = 0L
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        exoPlayer?.stop()
        stopForeground(true)
        (getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager).cancel(NOTIFICATION_ID)
        stopSelf()
        stopProgressUpdates()
    }

    fun togglePlayPause() {
        if (isPlaying) {
            pause()
        } else {
            play()
        }
    }

    fun next() {
        if (currentIndex < playlist.size - 1) {
            currentIndex++
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)

            // Usar startNewSong para preparar correctamente la nueva canción
            startNewSong()
            if (isPlaying) {
                updatePlaybackState()
                notifyPlaybackStateChanged(true)
                showOrUpdateNotification()
            }
        }
    }

    fun previous() {
        if (currentIndex > 0) {
            currentIndex--
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)

            // Usar startNewSong para preparar correctamente la nueva canción
            startNewSong()
            if (isPlaying) {
                updatePlaybackState()
                notifyPlaybackStateChanged(true)
                showOrUpdateNotification()
            }
        }
    }

    fun seekTo(position: Long) {
        currentPosition = position
        updatePlaybackState()
        exoPlayer?.seekTo(position)
    }

    fun playQueue(songs: List<Song>, startIndex: Int = 0) {
        playlist.clear()
        playlist.addAll(songs)
        currentIndex = startIndex
        currentSong = if (songs.isNotEmpty()) songs[startIndex] else null
        notifySongChanged(currentSong)
        notifyQueueChanged(playlist.toList())

        // Usar startNewSong para asegurar que se prepare correctamente
        startNewSong()
        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
        showOrUpdateNotification()
    }

    fun playSong(song: Song) {
        playlist.clear()
        playlist.add(song)
        currentIndex = 0
        currentSong = song
        notifySongChanged(currentSong)
        notifyQueueChanged(playlist.toList())

        // Usar startNewSong para asegurar que se prepare correctamente
        startNewSong()
        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
        showOrUpdateNotification()
    }

    // --- Notificación y metadata ---
    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                NOTIFICATION_CHANNEL_ID,
                getString(R.string.app_name),
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Reproducción de música"
                setSound(null, null)
                enableVibration(false)
            }
            val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            nm.createNotificationChannel(channel)
        }
    }

    private fun getContentPendingIntent(): PendingIntent? {
        // Abrir directamente PlayerActivity al tocar la notificación
        val intent = Intent(this, PlayerActivity::class.java).apply {
            addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)
        }
        return PendingIntent.getActivity(
            this,
            0,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
    }

    private fun buildBaseNotification(largeIcon: Bitmap? = null): NotificationCompat.Builder {
        val song = currentSong
        val title = song?.title ?: getString(R.string.app_name)
        val artist = song?.artist ?: ""

        val playPauseAction = NotificationCompat.Action(
            if (isPlaying) R.drawable.ic_pause else R.drawable.ic_play,
            if (isPlaying) getString(R.string.pause) else getString(R.string.play),
            MediaButtonReceiver.buildMediaButtonPendingIntent(
                this,
                PlaybackStateCompat.ACTION_PLAY_PAUSE
            )
        )
        val prevAction = NotificationCompat.Action(
            R.drawable.ic_arrow_back,
            getString(R.string.previous),
            MediaButtonReceiver.buildMediaButtonPendingIntent(
                this,
                PlaybackStateCompat.ACTION_SKIP_TO_PREVIOUS
            )
        )
        val nextAction = NotificationCompat.Action(
            R.drawable.ic_skip_next,
            getString(R.string.next),
            MediaButtonReceiver.buildMediaButtonPendingIntent(
                this,
                PlaybackStateCompat.ACTION_SKIP_TO_NEXT
            )
        )

        val style = MediaStyle()
            .setMediaSession(mediaSession.sessionToken)
            .setShowActionsInCompactView(0, 1, 2)

        val builder = NotificationCompat.Builder(this, NOTIFICATION_CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_music_note)
            .setContentTitle(title)
            .setContentText(artist)
            .setContentIntent(getContentPendingIntent())
            .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
            .setCategory(Notification.CATEGORY_TRANSPORT)
            .setOnlyAlertOnce(true)
            .setColor(ContextCompat.getColor(this, R.color.primary))
            .setStyle(style)
            .addAction(prevAction)
            .addAction(playPauseAction)
            .addAction(nextAction)

        if (largeIcon != null) builder.setLargeIcon(largeIcon)

        return builder
    }

    private fun showOrUpdateNotification() {
        val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        val isForeground = isPlaying

        // Cargar carátula en background y actualizar notificación
        val song = currentSong
        if (song != null && musicRepository.serverUrl != null) {
            val (u, t, s) = musicRepository.getAuthParams()
            val coverUrl = song.getCoverArtUrl(musicRepository.serverUrl!!, u, t, s)
            CoroutineScope(Dispatchers.IO).launch {
                val bitmap = try {
                    if (coverUrl != null) {
                        val future = com.bumptech.glide.Glide.with(this@MusicService)
                            .asBitmap()
                            .load(coverUrl)
                            .submit(256, 256)
                        future.get()
                    } else null
                } catch (_: Exception) { null }

                withContext(Dispatchers.Main) {
                    val notification = buildBaseNotification(bitmap).build()
                    if (isForeground) {
                        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                            startForeground(NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK)
                        } else {
                            startForeground(NOTIFICATION_ID, notification)
                        }
                    } else {
                        nm.notify(NOTIFICATION_ID, notification)
                        // Mantener notificación visible pero quitar foreground si está pausado
                        stopForeground(false)
                    }
                }
            }
        } else {
            val notification = buildBaseNotification(null).build()
            if (isForeground) {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                    startForeground(NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK)
                } else {
                    startForeground(NOTIFICATION_ID, notification)
                }
            } else {
                nm.notify(NOTIFICATION_ID, notification)
                stopForeground(false)
            }
        }
    }

    private fun updateMediaMetadata() {
        val song = currentSong ?: return
        val metadata = MediaMetadataCompat.Builder()
            .putString(MediaMetadataCompat.METADATA_KEY_TITLE, song.title)
            .putString(MediaMetadataCompat.METADATA_KEY_ARTIST, song.artist)
            .putString(MediaMetadataCompat.METADATA_KEY_ALBUM, song.album)
            .putLong(MediaMetadataCompat.METADATA_KEY_DURATION, (song.duration * 1000).toLong())
            .build()
        mediaSession.setMetadata(metadata)
    }

    // Getters para el estado actual
    fun getCurrentSong(): Song? = currentSong
    fun isPlaying(): Boolean = isPlaying
    fun getCurrentPosition(): Long = exoPlayer?.currentPosition ?: 0L
    fun getDuration(): Long = exoPlayer?.duration ?: 0L
    fun getQueue(): List<Song> = playlist.toList()
    fun getCurrentIndex(): Int = currentIndex

    // Métodos públicos para registrar listeners (compatibilidad con ArtistDetailFragment)
    fun setOnSongChangeListener(listener: ((Song?) -> Unit)?) {
        songChangeListeners.clear()
        listener?.let { songChangeListeners.add(it) }
    }

    fun setOnPlaybackStateChangeListener(listener: ((Boolean) -> Unit)?) {
        playbackStateListeners.clear()
        listener?.let { playbackStateListeners.add(it) }
    }

    // Listeners para cambios de estado
    private val queueChangeListeners = mutableListOf<(List<Song>) -> Unit>()

    fun addPlaybackStateListener(listener: (Boolean) -> Unit) {
        playbackStateListeners.add(listener)
    }

    fun addSongChangeListener(listener: (Song?) -> Unit) {
        songChangeListeners.add(listener)
    }

    fun addQueueChangeListener(listener: (List<Song>) -> Unit) {
        queueChangeListeners.add(listener)
    }

    fun removePlaybackStateListener(listener: (Boolean) -> Unit) {
        playbackStateListeners.remove(listener)
    }

    fun removeSongChangeListener(listener: (Song?) -> Unit) {
        songChangeListeners.remove(listener)
    }

    fun removeQueueChangeListener(listener: (List<Song>) -> Unit) {
        queueChangeListeners.remove(listener)
    }

    private fun notifyPlaybackStateChanged(isPlaying: Boolean) {
        playbackStateListeners.forEach { it(isPlaying) }
    }

    private fun notifySongChanged(song: Song?) {
        songChangeListeners.forEach { it(song) }
    }

    private fun notifyQueueChanged(queue: List<Song>) {
        queueChangeListeners.forEach { it(queue) }
    }

    private fun updatePlaybackState() {
        val position = exoPlayer?.currentPosition ?: currentPosition
        currentPosition = position
        val buffered = exoPlayer?.bufferedPosition ?: 0L
        val state = if (isPlaying) PlaybackStateCompat.STATE_PLAYING else PlaybackStateCompat.STATE_PAUSED
        val speed = if (isPlaying) 1.0f else 0.0f

        val playbackState = PlaybackStateCompat.Builder()
            .setState(state, position, speed)
            .setBufferedPosition(buffered)
            .setActions(
                PlaybackStateCompat.ACTION_PLAY_PAUSE or
                PlaybackStateCompat.ACTION_SKIP_TO_NEXT or
                PlaybackStateCompat.ACTION_SKIP_TO_PREVIOUS or
                PlaybackStateCompat.ACTION_SEEK_TO
            )
            .build()

        mediaSession.setPlaybackState(playbackState)
    }

    fun addToQueue(song: Song) {
        playlist.add(song)
        notifyQueueChanged(playlist.toList())
    }

    fun playNext(song: Song) {
        val insertPosition = currentIndex + 1
        if (insertPosition <= playlist.size) {
            playlist.add(insertPosition, song)
            notifyQueueChanged(playlist.toList())
        } else {
            addToQueue(song)
        }
    }

    fun shuffleQueue() {
        if (playlist.isEmpty()) return
        // Guardar orden original una sola vez
        if (originalQueue == null) {
            originalQueue = playlist.toMutableList()
        }
        val played = playlist.take(currentIndex + 1)
        val remaining = playlist.drop(currentIndex + 1).shuffled()
        playlist.clear()
        playlist.addAll(played + remaining)
        notifyQueueChanged(playlist.toList())
    }

    fun unshuffleQueue() {
        val original = originalQueue ?: return
        // Mantener la canción actual si existe
        val current = currentSong
        playlist.clear()
        playlist.addAll(original)
        originalQueue = null
        currentIndex = current?.let { song -> playlist.indexOfFirst { it.id == song.id } }.takeIf { it != null && it >= 0 } ?: 0
        currentSong = playlist.getOrNull(currentIndex)
        notifyQueueChanged(playlist.toList())
    }

    fun setRepeatMode(mode: RepeatMode) {
        repeatMode = mode
        // Mapear con ExoPlayer: solo repetir UNA pista a nivel ExoPlayer.
        // Para repetir TODA la cola, mantenemos REPEAT_MODE_OFF y dejamos que la lógica
        // de onPlaybackStateChanged avance por la playlist y regrese al inicio.
        val exoMode = when (mode) {
            RepeatMode.OFF -> com.google.android.exoplayer2.Player.REPEAT_MODE_OFF
            RepeatMode.ALL -> com.google.android.exoplayer2.Player.REPEAT_MODE_OFF
            RepeatMode.ONE -> com.google.android.exoplayer2.Player.REPEAT_MODE_ONE
        }
        exoPlayer?.repeatMode = exoMode
    }

    fun getRepeatMode(): RepeatMode = repeatMode

    fun playFromQueue(index: Int) {
        if (index in 0 until playlist.size) {
            currentIndex = index
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)
            startNewSong()
            isPlaying = true
            updatePlaybackState()
            notifyPlaybackStateChanged(true)
            showOrUpdateNotification()
        }
    }

    fun removeFromQueue(index: Int) {
        if (index in 0 until playlist.size) {
            playlist.removeAt(index)
            when {
                index < currentIndex -> currentIndex--
                index == currentIndex -> {
                    if (playlist.isNotEmpty()) {
                        if (currentIndex >= playlist.size) currentIndex = playlist.size - 1
                        currentSong = playlist[currentIndex]
                        notifySongChanged(currentSong)
                        startNewSong()
                    } else {
                        currentSong = null
                        notifySongChanged(null)
                        stop()
                    }
                }
            }
            notifyQueueChanged(playlist.toList())
        }
    }

    fun moveInQueue(fromIndex: Int, toIndex: Int) {
        if (fromIndex in 0 until playlist.size && toIndex in 0 until playlist.size) {
            val song = playlist.removeAt(fromIndex)
            playlist.add(toIndex, song)

            // Actualizar currentIndex si es necesario
            currentIndex = when {
                fromIndex == currentIndex -> toIndex
                fromIndex < currentIndex && toIndex >= currentIndex -> currentIndex - 1
                fromIndex > currentIndex && toIndex <= currentIndex -> currentIndex + 1
                else -> currentIndex
            }

            notifyQueueChanged(playlist.toList())
        }
    }

    // Inicia y detiene actualizaciones periódicas del progreso para la notificación/lockscreen
    private fun startProgressUpdates() {
        progressJob?.cancel()
        progressJob = CoroutineScope(Dispatchers.Main).launch {
            while (isPlaying) {
                updatePlaybackState()
                delay(1000L)
            }
        }
    }

    private fun stopProgressUpdates() {
        progressJob?.cancel()
        progressJob = null
    }

    private fun prefetchSimilarForCurrentSong() {
        val base = currentSong ?: return
        CoroutineScope(Dispatchers.IO).launch {
            try {
                val result = musicRepository.getSimilarSongs(base.id, size = 15)
                val list = result.getOrNull().orEmpty()
                    .filter { it.id != base.id }
                    .filter { s -> playlist.none { it.id == s.id } }
                if (list.isNotEmpty()) {
                    prefetchedSimilar = list
                }
            } catch (_: Exception) {
                // Ignorar errores de prefetch
            }
        }
    }

    private fun continueWithSimilarSongs() {
        val baseSong = currentSong
        if (baseSong == null) {
            stopAtEnd()
            return
        }
        CoroutineScope(Dispatchers.IO).launch {
            try {
                val similarResult = musicRepository.getSimilarSongs(baseSong.id, size = 15)
                val similar = similarResult.getOrNull()
                    ?.filter { it.id != baseSong.id }
                    ?.filter { s -> playlist.none { it.id == s.id } }
                    ?: emptyList()

                if (similar.isNotEmpty()) {
                    withContext(Dispatchers.Main) {
                        playlist.addAll(similar)
                        notifyQueueChanged(playlist.toList())
                        next()
                        // Prefetch para la nueva canción
                        prefetchSimilarForCurrentSong()
                    }
                } else {
                    val randomResult = musicRepository.getRandomSongs(size = 15)
                    val randomSongs = randomResult.getOrNull()?.filter { s -> playlist.none { it.id == s.id } } ?: emptyList()
                    if (randomSongs.isNotEmpty()) {
                        withContext(Dispatchers.Main) {
                            playlist.addAll(randomSongs)
                            notifyQueueChanged(playlist.toList())
                            next()
                            prefetchSimilarForCurrentSong()
                        }
                    } else {
                        withContext(Dispatchers.Main) { stopAtEnd() }
                    }
                }
            } catch (_: Exception) {
                withContext(Dispatchers.Main) { stopAtEnd() }
            }
        }
    }

    private fun stopAtEnd() {
        isPlaying = false
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        showOrUpdateNotification()
    }
}

package com.arantec.castafiore.ui.activities

import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.content.ServiceConnection
import android.graphics.Color
import android.os.Bundle
import android.os.Handler
import android.os.IBinder
import android.os.Looper
import android.view.View
import android.widget.SeekBar
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.palette.graphics.Palette
import kotlinx.coroutines.launch
import com.arantec.castafiore.R
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.data.download.SongDownloadManager
import com.arantec.castafiore.databinding.ActivityPlayerBinding
import com.arantec.castafiore.service.MusicService
import com.arantec.castafiore.ui.dialogs.SongOptionsBottomSheet
import com.arantec.castafiore.ui.dialogs.PlaylistSelectorBottomSheet
import com.arantec.castafiore.utils.StatusBarUtils
import com.bumptech.glide.Glide
import com.bumptech.glide.request.target.CustomTarget
import com.bumptech.glide.request.transition.Transition
import android.graphics.Bitmap
import android.graphics.drawable.Drawable

class PlayerActivity : AppCompatActivity() {

    private lateinit var binding: ActivityPlayerBinding

    private lateinit var musicRepository: MusicRepository
    private var musicService: MusicService? = null
    private var isBound = false

    private var currentSong: Song? = null
    private var isPlaying = false
    private var isShuffleEnabled = false
    private var repeatMode = RepeatMode.OFF
    private var isFavorite = false

    // Handler para actualizar la progress bar
    private val handler = Handler(Looper.getMainLooper())
    private var updateProgressRunnable: Runnable? = null

    private enum class RepeatMode {
        OFF, ALL, ONE
    }

    private val serviceConnection = object : ServiceConnection {
        override fun onServiceConnected(name: ComponentName?, service: IBinder?) {
            val binder = service as MusicService.MusicBinder
            musicService = binder.getService()
            isBound = true
            android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onServiceConnected: shuffle state before updateUIFromService = $isShuffleEnabled")
            android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onServiceConnected: repeat mode before updateUIFromService = $repeatMode")

            // NO re-aplicar shuffle automáticamente al reconectar - la cola ya está en el estado correcto
            // Solo sincronizar el repeat mode con el servicio
            val serviceRepeatMode = when (repeatMode) {
                RepeatMode.OFF -> MusicService.RepeatMode.OFF
                RepeatMode.ALL -> MusicService.RepeatMode.ALL
                RepeatMode.ONE -> MusicService.RepeatMode.ONE
            }
            musicService?.setRepeatMode(serviceRepeatMode)
            android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onServiceConnected: Syncing repeat mode with service = $repeatMode")

            setupMusicServiceListeners()
            updateUIFromService()
        }

        override fun onServiceDisconnected(name: ComponentName?) {
            isBound = false
            musicService = null
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityPlayerBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Configurar pantalla completa inmersiva
        setupFullScreenMode()

        musicRepository = MusicRepository.getInstance(this)

        // Restaurar el estado de shuffle y repeat desde SharedPreferences
        val prefs = getSharedPreferences("player_prefs", Context.MODE_PRIVATE)
        isShuffleEnabled = prefs.getBoolean("shuffle_mode", false)
        val savedRepeatMode = prefs.getInt("repeat_mode", RepeatMode.OFF.ordinal)
        repeatMode = RepeatMode.values()[savedRepeatMode]
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onCreate: Restored shuffle state from SharedPreferences = $isShuffleEnabled")
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onCreate: Restored repeat mode from SharedPreferences = $repeatMode")
        updateShuffleButton()
        updateRepeatButton()

        setupClickListeners()
        bindMusicService()
    }

    private fun setupFullScreenMode() {
        // Ocultar la barra de navegación y hacer la experiencia inmersiva
        window.decorView.systemUiVisibility = (
            View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
            or View.SYSTEM_UI_FLAG_LAYOUT_STABLE
            or View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION
            or View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
            or View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
            or View.SYSTEM_UI_FLAG_FULLSCREEN
        )

        // Aplicar color de status bar estático
        StatusBarUtils.setStatusBarColor(this)
    }

    private fun setupClickListeners() {
        binding.btnBack.setOnClickListener {
            finish()
        }

        binding.btnPlayPause.setOnClickListener {
            togglePlayPause()
        }

        binding.btnNext.setOnClickListener {
            playNext()
        }

        binding.btnPrevious.setOnClickListener {
            playPrevious()
        }

        binding.btnShuffle.setOnClickListener {
            toggleShuffle()
        }

        binding.btnRepeat.setOnClickListener {
            toggleRepeat()
        }

        binding.btnFavorite.setOnClickListener {
            toggleFavorite()
        }


        binding.btnQueue.setOnClickListener {
            // Abrir la cola de reproducción
            val intent = Intent(this, QueueActivity::class.java)
            startActivity(intent)
        }

        binding.btnMore.setOnClickListener {
            // Mostrar opciones de la canción actual
            currentSong?.let { song ->
                val bottomSheet = SongOptionsBottomSheet.newInstance(song, isFavorite)
                    .setOnDownloadClickListener { downloadSong ->
                        // Implementar descarga de la canción
                        val downloadManager = SongDownloadManager.getInstance(this@PlayerActivity)
                        if (!downloadManager.isSongDownloaded(downloadSong.id)) {
                            downloadManager.downloadSong(downloadSong)
                            showMessage("Descarga iniciada: ${downloadSong.title}")
                        } else {
                            showMessage("La canción ya está descargada")
                        }
                    }
                    .setOnDeleteDownloadClickListener { downloadSong ->
                        // Implementar eliminación de descarga
                        val downloadManager = SongDownloadManager.getInstance(this@PlayerActivity)
                        if (downloadManager.isSongDownloaded(downloadSong.id)) {
                            val success = downloadManager.deleteSong(downloadSong.id)
                            if (success) {
                                showMessage("Descarga eliminada: ${downloadSong.title}")
                            } else {
                                showMessage("Error al eliminar descarga")
                            }
                        } else {
                            showMessage("La canción no está descargada")
                        }
                    }
                    // Ocultar las opciones que no tienen sentido para la canción que se está reproduciendo
                    .hideAddToQueueOption()
                    .hidePlayNextOption()
                    .setOnAddToPlaylistClickListener { playlistSong ->
                        // Mostrar diálogo selector de playlists
                        val playlistSelector = PlaylistSelectorBottomSheet.newInstance(playlistSong)
                        playlistSelector.show(supportFragmentManager, "PlaylistSelectorBottomSheet")
                    }
                    .setOnViewAlbumClickListener { albumSong ->
                        // Navegar al álbum de la canción
                        navigateToAlbum(albumSong)
                    }
                    .setOnViewArtistClickListener { artistSong ->
                        // Navegar al artista de la canción
                        navigateToArtist(artistSong)
                    }
                    .setOnShareClickListener { shareSong ->
                        shareCurrentSong()
                    }
                    .setOnSongInfoClickListener { infoSong ->
                        showSongInfoDialog(infoSong)
                    }

                bottomSheet.show(supportFragmentManager, "SongOptionsBottomSheet")
            } ?: showMessage("No hay canción reproduciéndose")
        }

        // SeekBar listener para el progreso
        binding.seekBarProgress.setOnSeekBarChangeListener(object : SeekBar.OnSeekBarChangeListener {
            override fun onProgressChanged(seekBar: SeekBar?, progress: Int, fromUser: Boolean) {
                if (fromUser) {
                    val duration = currentSong?.duration ?: 0
                    val position = (progress * duration / 100).toLong()
                    binding.tvCurrentTime.text = formatTime(position)
                }
            }

            override fun onStartTrackingTouch(seekBar: SeekBar?) {
                stopProgressUpdates()
            }

            override fun onStopTrackingTouch(seekBar: SeekBar?) {
                seekBar?.let {
                    val duration = currentSong?.duration ?: 0
                    val position = (it.progress * duration / 100).toLong()
                    musicService?.seekTo(position * 1000) // ExoPlayer usa milisegundos
                }
                startProgressUpdates()
            }
        })
    }

    private fun bindMusicService() {
        val intent = Intent(this, MusicService::class.java)
        bindService(intent, serviceConnection, Context.BIND_AUTO_CREATE)
    }

    private fun unbindMusicService() {
        if (isBound) {
            unbindService(serviceConnection)
            isBound = false
            musicService = null
        }
    }

    private fun setupMusicServiceListeners() {
        musicService?.let { service ->
            // Agregar listener para cambios de estado de reproducción
            service.addPlaybackStateListener { playing ->
                isPlaying = playing
                updatePlayPauseButton()
                if (playing) {
                    startProgressUpdates()
                } else {
                    stopProgressUpdates()
                }
            }

            // Agregar listener para cambios de canción
            service.addSongChangeListener { song ->
                currentSong = song
                song?.let { 
                    updateSongInfo(it)
                    loadAlbumArt(it)
                    checkFavoriteStatus(it)
                }
            }
        }
    }

    private fun updateUIFromService() {
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] updateUIFromService: shuffle state = $isShuffleEnabled")
        musicService?.let { service ->
            currentSong = service.getCurrentSong()
            isPlaying = service.isPlaying()

            currentSong?.let { song ->
                updateSongInfo(song)
                loadAlbumArt(song)
                checkFavoriteStatus(song)
            }

            updatePlayPauseButton()
            updateShuffleButton()
            updateRepeatButton()
            updateProgressBar()

            // Solo iniciar actualizaciones si está reproduciéndose
            if (isPlaying) {
                startProgressUpdates()
            }
        }
    }

    private fun updateSongInfo(song: Song) {
        binding.tvSongTitle.text = song.title
        binding.tvArtistName.text = song.artist
        binding.tvPlayingFrom.text = song.album ?: "Unknown Album"
        binding.tvTotalTime.text = formatTime(song.duration?.toLong() ?: 0)

        // Actualizar el máximo del SeekBar
        val duration = song.duration ?: 0
        binding.seekBarProgress.max = 100 // Usamos porcentajes para mejor control
    }

    private fun loadAlbumArt(song: Song) {
        try {
            val (username, token, salt) = musicRepository.getAuthParams()
            val coverUrl = if (song.albumId != null) {
                "${musicRepository.serverUrl}/rest/getCoverArt.view?id=${song.albumId}&u=$username&t=$token&s=$salt&v=1.16.1&c=Castafiore&size=500"
            } else {
                null
            }

            if (coverUrl != null) {
                Glide.with(this)
                    .asBitmap()
                    .load(coverUrl)
                    .placeholder(R.drawable.ic_album_placeholder)
                    .error(R.drawable.ic_album_placeholder)
                    .into(object : CustomTarget<Bitmap>() {
                        override fun onResourceReady(resource: Bitmap, transition: Transition<in Bitmap>?) {
                            binding.ivAlbumCover.setImageBitmap(resource)
                            extractColorsAndApplyTheme(resource)
                        }

                        override fun onLoadCleared(placeholder: Drawable?) {
                            binding.ivAlbumCover.setImageDrawable(placeholder)
                            applyDefaultTheme()
                        }
                    })
            } else {
                binding.ivAlbumCover.setImageResource(R.drawable.ic_album_placeholder)
                applyDefaultTheme()
            }
        } catch (e: Exception) {
            binding.ivAlbumCover.setImageResource(R.drawable.ic_album_placeholder)
            applyDefaultTheme()
        }
    }

    private fun extractColorsAndApplyTheme(bitmap: Bitmap) {
        Palette.from(bitmap).generate { palette ->
            palette?.let {
                val dominantColor = it.getDominantColor(Color.parseColor("#121212"))
                val vibrantColor = it.getVibrantColor(dominantColor)

                // Aplicar color estático por ahora (consistente con el resto de la app)
                applyDefaultTheme()
            } ?: applyDefaultTheme()
        }
    }

    private fun applyDefaultTheme() {
        // Aplicar tema estático consistente
        val staticColor = Color.parseColor("#121212")
        binding.gradientBackground.setBackgroundColor(staticColor)
        StatusBarUtils.setStatusBarColor(this)
    }

    private fun togglePlayPause() {
        musicService?.let { service ->
            if (service.isPlaying()) {
                service.pause()
            } else {
                service.resume()
            }
            // El estado se actualizará automáticamente a través del listener
        }
    }

    private fun playNext() {
        musicService?.next()
    }

    private fun playPrevious() {
        musicService?.previous()
    }

    private fun toggleShuffle() {
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleShuffle: Before toggle = $isShuffleEnabled")
        isShuffleEnabled = !isShuffleEnabled
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleShuffle: After toggle = $isShuffleEnabled")
        updateShuffleButton()

        // Guardar el estado en SharedPreferences
        val prefs = getSharedPreferences("player_prefs", Context.MODE_PRIVATE)
        prefs.edit().putBoolean("shuffle_mode", isShuffleEnabled).apply()
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleShuffle: Saved to SharedPreferences = $isShuffleEnabled")

        if (isShuffleEnabled) {
            musicService?.shuffleQueue()
        } else {
            musicService?.unshuffleQueue()
        }
    }

    private fun toggleRepeat() {
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleRepeat: Before toggle = $repeatMode")
        repeatMode = when (repeatMode) {
            RepeatMode.OFF -> RepeatMode.ALL
            RepeatMode.ALL -> RepeatMode.ONE
            RepeatMode.ONE -> RepeatMode.OFF
        }
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleRepeat: After toggle = $repeatMode")
        updateRepeatButton()

        // Guardar el estado en SharedPreferences
        val prefs = getSharedPreferences("player_prefs", Context.MODE_PRIVATE)
        prefs.edit().putInt("repeat_mode", repeatMode.ordinal).apply()
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleRepeat: Saved to SharedPreferences = $repeatMode")

        // Sincronizar el estado con el servicio
        val serviceRepeatMode = when (repeatMode) {
            RepeatMode.OFF -> MusicService.RepeatMode.OFF
            RepeatMode.ALL -> MusicService.RepeatMode.ALL
            RepeatMode.ONE -> MusicService.RepeatMode.ONE
        }
        musicService?.setRepeatMode(serviceRepeatMode)
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleRepeat: Synced with MusicService = $repeatMode")
    }

    private fun toggleFavorite() {
        currentSong?.let { song ->
            lifecycleScope.launch {
                try {
                    val result = if (isFavorite) {
                        // Si ya es favorito, quitar de favoritos
                        musicRepository.unstarSong(song.id)
                    } else {
                        // Si no es favorito, agregar a favoritos
                        musicRepository.starSong(song.id)
                    }

                    result.fold(
                        onSuccess = {
                            // Actualizar el estado local
                            isFavorite = !isFavorite
                            updateFavoriteButton()

                            val message = if (isFavorite) {
                                "Agregado a favoritos"
                            } else {
                                "Eliminado de favoritos"
                            }
                            showMessage(message)
                        },
                        onFailure = { exception ->
                            showMessage("Error al actualizar favoritos: ${exception.message}")
                        }
                    )
                } catch (e: Exception) {
                    showMessage("Error al actualizar favoritos: ${e.message}")
                }
            }
        }
    }

    private fun checkFavoriteStatus(song: Song) {
        lifecycleScope.launch {
            try {
                val result = musicRepository.isSongStarred(song.id)
                result.fold(
                    onSuccess = { isStarred ->
                        isFavorite = isStarred
                        updateFavoriteButton()
                    },
                    onFailure = {
                        // En caso de error, asumir que no es favorito
                        isFavorite = false
                        updateFavoriteButton()
                    }
                )
            } catch (e: Exception) {
                // En caso de excepción, asumir que no es favorito
                isFavorite = false
                updateFavoriteButton()
            }
        }
    }

    private fun shareCurrentSong() {
        currentSong?.let { song ->
            val shareText = "Escuchando: ${song.title} - ${song.artist}"
            val shareIntent = Intent().apply {
                action = Intent.ACTION_SEND
                type = "text/plain"
                putExtra(Intent.EXTRA_TEXT, shareText)
            }

            val chooser = Intent.createChooser(shareIntent, "Compartir canción")
            startActivity(chooser)
        }
    }

    private fun updatePlayPauseButton() {
        val iconRes = if (isPlaying) R.drawable.ic_pause else R.drawable.ic_play
        binding.btnPlayPause.setImageResource(iconRes)
    }

    private fun updateShuffleButton() {
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] updateShuffleButton: Using shuffle state = $isShuffleEnabled")
        val tint = if (isShuffleEnabled) {
            getColor(R.color.primary)
        } else {
            getColor(R.color.text_secondary)
        }
        binding.btnShuffle.imageTintList = android.content.res.ColorStateList.valueOf(tint)
    }

    private fun updateRepeatButton() {
        val (iconRes, tint) = when (repeatMode) {
            RepeatMode.OFF -> R.drawable.ic_repeat to getColor(R.color.text_secondary)
            RepeatMode.ALL -> R.drawable.ic_repeat to getColor(R.color.primary)
            RepeatMode.ONE -> R.drawable.ic_repeat_one to getColor(R.color.primary)
        }

        binding.btnRepeat.setImageResource(iconRes)
        binding.btnRepeat.imageTintList = android.content.res.ColorStateList.valueOf(tint)
    }

    private fun updateFavoriteButton() {
        val iconRes = if (isFavorite) R.drawable.ic_favorite else R.drawable.ic_favorite_border
        val tint = if (isFavorite) {
            getColor(R.color.primary)
        } else {
            getColor(R.color.text_secondary)
        }

        binding.btnFavorite.setImageResource(iconRes)
        binding.btnFavorite.imageTintList = android.content.res.ColorStateList.valueOf(tint)
    }

    private fun updateProgressBar() {
        musicService?.let { service ->
            val currentPosition = service.getCurrentPosition()
            val duration = currentSong?.duration?.toLong() ?: 1

            if (duration > 0) {
                val progress = ((currentPosition / 1000) * 100 / duration).toInt()
                binding.seekBarProgress.progress = progress
                binding.tvCurrentTime.text = formatTime(currentPosition / 1000)
            }
        }
    }

    private fun startProgressUpdates() {
        stopProgressUpdates()
        updateProgressRunnable = object : Runnable {
            override fun run() {
                if (isPlaying && isBound) {
                    updateProgressBar()
                    handler.postDelayed(this, 1000)
                }
            }
        }
        updateProgressRunnable?.let { handler.post(it) }
    }

    private fun stopProgressUpdates() {
        updateProgressRunnable?.let {
            handler.removeCallbacks(it)
            updateProgressRunnable = null
        }
    }

    private fun formatTime(seconds: Long): String {
        val minutes = seconds / 60
        val secs = seconds % 60
        return String.format("%d:%02d", minutes, secs)
    }

    private fun showMessage(message: String) {
        android.widget.Toast.makeText(this, message, android.widget.Toast.LENGTH_SHORT).show()
    }

    private fun navigateToAlbum(song: Song) {
        // Verificar que la canción tenga información del álbum
        val albumId = song.albumId
        val albumName = song.album

        if (albumId != null && albumName != null) {
            // Como AlbumDetailFragment usa Navigation Component, necesitamos volver a MainActivity
            // y navegar usando Navigation Component
            val intent = Intent(this, MainActivity::class.java).apply {
                // Agregar flags para limpiar el stack y crear una nueva tarea
                flags = Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP
                // Pasar información del álbum para que MainActivity pueda navegar al fragmento correcto
                putExtra("navigate_to", "album_detail")
                putExtra("album_id", albumId)
                putExtra("album_name", albumName)
                // Agregar información adicional del artista
                putExtra("artist_name", song.artist)
                putExtra("artist_id", song.artistId)
            }
            startActivity(intent)
            finish() // Cerrar PlayerActivity
        } else {
            showMessage("Información del álbum no disponible")
        }
    }

    private fun navigateToArtist(song: Song) {
        // Verificar que la canción tenga información del artista
        val artistId = song.artistId
        val artistName = song.artist

        android.util.Log.d("PlayerActivity", "navigateToArtist called - artistId: $artistId, artistName: $artistName")

        if (artistId != null && artistName != null) {
            // Como ArtistDetailFragment usa Navigation Component, necesitamos volver a MainActivity
            val intent = Intent(this, MainActivity::class.java).apply {
                // Agregar flags para limpiar el stack y crear una nueva tarea
                flags = Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP
                // Pasar información del artista para que MainActivity pueda navegar al fragmento correcto
                putExtra("navigate_to", "artist_detail")
                putExtra("artist_id", artistId)
                putExtra("artist_name", artistName)
            }
            android.util.Log.d("PlayerActivity", "Starting MainActivity with artist_detail navigation")
            startActivity(intent)
            finish() // Cerrar PlayerActivity
        } else {
            showMessage("Información del artista no disponible")
        }
    }

    private fun showSongInfoDialog(song: Song) {
        val dialogBuilder = androidx.appcompat.app.AlertDialog.Builder(this)

        // Crear el layout del diálogo
        val dialogView = layoutInflater.inflate(R.layout.dialog_song_info, null)

        // Referencias a las vistas del diálogo
        val tvTitle = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_title)
        val tvArtist = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_artist)
        val tvAlbum = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_album)
        val tvDuration = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_duration)
        val tvGenre = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_genre)
        val tvYear = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_year)
        val tvBitrate = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_bitrate)
        val tvFormat = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_format)
        val tvFileSize = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_file_size)
        val ivCover = dialogView.findViewById<android.widget.ImageView>(R.id.iv_info_cover)

        // Llenar la información
        tvTitle.text = song.title
        tvArtist.text = song.artist ?: "Artista desconocido"
        tvAlbum.text = song.album ?: "Álbum desconocido"
        tvDuration.text = formatTime(song.duration?.toLong() ?: 0)
        tvGenre.text = song.genre ?: "Género desconocido"
        tvYear.text = song.year?.toString() ?: "Año desconocido"
        tvBitrate.text = if (song.bitRate != null) "${song.bitRate} kbps" else "Bitrate desconocido"
        tvFormat.text = song.suffix?.uppercase() ?: "Formato desconocido"
        tvFileSize.text = if (song.size != null) {
            val sizeInMB = song.size / (1024.0 * 1024.0)
            String.format("%.1f MB", sizeInMB)
        } else {
            "Tamaño desconocido"
        }

        // Cargar la portada del álbum
        try {
            val (username, token, salt) = musicRepository.getAuthParams()
            val coverUrl = if (song.albumId != null) {
                "${musicRepository.serverUrl}/rest/getCoverArt.view?id=${song.albumId}&u=$username&t=$token&s=$salt&v=1.16.1&c=Castafiore&size=300"
            } else {
                null
            }

            if (coverUrl != null) {
                Glide.with(this)
                    .load(coverUrl)
                    .placeholder(R.drawable.ic_album_placeholder)
                    .error(R.drawable.ic_album_placeholder)
                    .into(ivCover)
            } else {
                ivCover.setImageResource(R.drawable.ic_album_placeholder)
            }
        } catch (e: Exception) {
            ivCover.setImageResource(R.drawable.ic_album_placeholder)
        }

        dialogBuilder.setView(dialogView)
            .setTitle("Información de la canción")
            .setPositiveButton("Cerrar") { dialog, _ ->
                dialog.dismiss()
            }
            .create()
            .show()
    }

    override fun onStart() {
        super.onStart()
        if (!isBound) {
            bindMusicService()
        }
    }

    override fun onResume() {
        super.onResume()
        StatusBarUtils.setStatusBarColor(this)

        // Reestablecer modo de pantalla completa
        setupFullScreenMode()

        // Actualizar estado desde el servicio
        if (isBound && musicService != null) {
            updateUIFromService()
        }

        // Reiniciar actualizaciones de progreso
        if (isPlaying) {
            startProgressUpdates()
        }
    }

    override fun onPause() {
        super.onPause()
        stopProgressUpdates()
    }

    override fun onStop() {
        super.onStop()
        stopProgressUpdates()
        unbindMusicService()
    }

    override fun onDestroy() {
        super.onDestroy()
        stopProgressUpdates()
    }
}

package com.arantec.castafiore.ui.activities

import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.content.ServiceConnection
import android.graphics.Color
import android.os.Build
import android.os.Bundle
import android.os.Handler
import android.os.IBinder
import android.os.Looper
import android.view.View
import android.view.WindowInsets
import android.widget.SeekBar
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.palette.graphics.Palette
import kotlinx.coroutines.launch
import com.arantec.castafiore.R
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.data.download.SongDownloadManager
import com.arantec.castafiore.databinding.ActivityPlayerBinding
import com.arantec.castafiore.service.MusicService
import com.arantec.castafiore.ui.dialogs.SongOptionsBottomSheet
import com.arantec.castafiore.ui.dialogs.PlaylistSelectorBottomSheet
import com.arantec.castafiore.utils.StatusBarUtils
import com.bumptech.glide.Glide
import com.bumptech.glide.request.target.CustomTarget
import com.bumptech.glide.request.transition.Transition
import android.graphics.Bitmap
import android.graphics.drawable.Drawable

class PlayerActivity : AppCompatActivity() {

    private lateinit var binding: ActivityPlayerBinding

    private lateinit var musicRepository: MusicRepository
    private var musicService: MusicService? = null
    private var isBound = false

    private var currentSong: Song? = null
    private var isPlaying = false
    private var isShuffleEnabled = false
    private var repeatMode = RepeatMode.OFF
    private var isFavorite = false

    // Handler para actualizar la progress bar
    private val handler = Handler(Looper.getMainLooper())
    private var updateProgressRunnable: Runnable? = null

    private enum class RepeatMode {
        OFF, ALL, ONE
    }

    private val serviceConnection = object : ServiceConnection {
        override fun onServiceConnected(name: ComponentName?, service: IBinder?) {
            val binder = service as MusicService.MusicBinder
            musicService = binder.getService()
            isBound = true
            android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onServiceConnected: shuffle state before updateUIFromService = $isShuffleEnabled")
            android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onServiceConnected: repeat mode before updateUIFromService = $repeatMode")

            // NO re-aplicar shuffle automáticamente al reconectar - la cola ya está en el estado correcto
            // Solo sincronizar el repeat mode con el servicio
            val serviceRepeatMode = when (repeatMode) {
                RepeatMode.OFF -> MusicService.RepeatMode.OFF
                RepeatMode.ALL -> MusicService.RepeatMode.ALL
                RepeatMode.ONE -> MusicService.RepeatMode.ONE
            }
            musicService?.setRepeatMode(serviceRepeatMode)
            android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onServiceConnected: Syncing repeat mode with service = $repeatMode")

            setupMusicServiceListeners()
            updateUIFromService()
        }

        override fun onServiceDisconnected(name: ComponentName?) {
            isBound = false
            musicService = null
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityPlayerBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Configurar pantalla completa inmersiva
        setupFullScreenMode()

        musicRepository = MusicRepository.getInstance(this)

        // Restaurar el estado de shuffle y repeat desde SharedPreferences
        val prefs = getSharedPreferences("player_prefs", Context.MODE_PRIVATE)
        isShuffleEnabled = prefs.getBoolean("shuffle_mode", false)
        val savedRepeatMode = prefs.getInt("repeat_mode", RepeatMode.OFF.ordinal)
        repeatMode = RepeatMode.values()[savedRepeatMode]
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onCreate: Restored shuffle state from SharedPreferences = $isShuffleEnabled")
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] onCreate: Restored repeat mode from SharedPreferences = $repeatMode")
        updateShuffleButton()
        updateRepeatButton()

        setupClickListeners()
        bindMusicService()
    }

    private fun setupFullScreenMode() {
        // Hacer visibles la status bar y la navigation bar
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            window.insetsController?.show(
                WindowInsets.Type.statusBars() or WindowInsets.Type.navigationBars()
            )
        } else {
            @Suppress("DEPRECATION")
            run {
                // Remover flags inmersivos y dejar solo layout estable
                window.decorView.systemUiVisibility = View.SYSTEM_UI_FLAG_LAYOUT_STABLE
            }
        }

        // Asegurar que el color de la status bar coincida con el fondo del player
        StatusBarUtils.setStatusBarColor(this)
    }

    private fun setupClickListeners() {
        binding.btnBack.setOnClickListener {
            finish()
        }

        binding.btnPlayPause.setOnClickListener {
            togglePlayPause()
        }

        binding.btnNext.setOnClickListener {
            playNext()
        }

        binding.btnPrevious.setOnClickListener {
            playPrevious()
        }

        binding.btnShuffle.setOnClickListener {
            toggleShuffle()
        }

        binding.btnRepeat.setOnClickListener {
            toggleRepeat()
        }

        binding.btnFavorite.setOnClickListener {
            toggleFavorite()
        }


        binding.btnQueue.setOnClickListener {
            // Abrir la cola de reproducción
            val intent = Intent(this, QueueActivity::class.java)
            startActivity(intent)
        }

        binding.btnMore.setOnClickListener {
            // Mostrar opciones de la canción actual
            currentSong?.let { song ->
                val bottomSheet = SongOptionsBottomSheet.newInstance(song, isFavorite)
                    .setOnDownloadClickListener { downloadSong ->
                        // Implementar descarga de la canción
                        val downloadManager = SongDownloadManager.getInstance(this@PlayerActivity)
                        if (!downloadManager.isSongDownloaded(downloadSong.id)) {
                            downloadManager.downloadSong(downloadSong)
                            showMessage("Descarga iniciada: ${downloadSong.title}")
                        } else {
                            showMessage("La canción ya está descargada")
                        }
                    }
                    .setOnDeleteDownloadClickListener { downloadSong ->
                        // Implementar eliminación de descarga
                        val downloadManager = SongDownloadManager.getInstance(this@PlayerActivity)
                        if (downloadManager.isSongDownloaded(downloadSong.id)) {
                            val success = downloadManager.deleteSong(downloadSong.id)
                            if (success) {
                                showMessage("Descarga eliminada: ${downloadSong.title}")
                            } else {
                                showMessage("Error al eliminar descarga")
                            }
                        } else {
                            showMessage("La canción no está descargada")
                        }
                    }
                    // Ocultar las opciones que no tienen sentido para la canción que se está reproduciendo
                    .hideAddToQueueOption()
                    .hidePlayNextOption()
                    .setOnAddToPlaylistClickListener { playlistSong ->
                        // Mostrar diálogo selector de playlists
                        val playlistSelector = PlaylistSelectorBottomSheet.newInstance(playlistSong)
                        playlistSelector.show(supportFragmentManager, "PlaylistSelectorBottomSheet")
                    }
                    .setOnViewAlbumClickListener { albumSong ->
                        // Navegar al álbum de la canción
                        navigateToAlbum(albumSong)
                    }
                    .setOnViewArtistClickListener { artistSong ->
                        // Navegar al artista de la canción
                        navigateToArtist(artistSong)
                    }
                    .setOnShareClickListener { shareSong ->
                        shareCurrentSong()
                    }
                    .setOnSongInfoClickListener { infoSong ->
                        showSongInfoDialog(infoSong)
                    }

                bottomSheet.show(supportFragmentManager, "SongOptionsBottomSheet")
            } ?: showMessage("No hay canción reproduciéndose")
        }

        // SeekBar listener para el progreso
        binding.seekBarProgress.setOnSeekBarChangeListener(object : SeekBar.OnSeekBarChangeListener {
            override fun onProgressChanged(seekBar: SeekBar?, progress: Int, fromUser: Boolean) {
                if (fromUser) {
                    val duration = currentSong?.duration ?: 0
                    val position = (progress * duration / 100).toLong()
                    binding.tvCurrentTime.text = formatTime(position)
                }
            }

            override fun onStartTrackingTouch(seekBar: SeekBar?) {
                stopProgressUpdates()
            }

            override fun onStopTrackingTouch(seekBar: SeekBar?) {
                seekBar?.let {
                    val duration = currentSong?.duration ?: 0
                    val position = (it.progress * duration / 100).toLong()
                    musicService?.seekTo(position * 1000) // ExoPlayer usa milisegundos
                }
                startProgressUpdates()
            }
        })
    }

    private fun bindMusicService() {
        val intent = Intent(this, MusicService::class.java)
        bindService(intent, serviceConnection, Context.BIND_AUTO_CREATE)
    }

    private fun unbindMusicService() {
        if (isBound) {
            unbindService(serviceConnection)
            isBound = false
            musicService = null
        }
    }

    private fun setupMusicServiceListeners() {
        musicService?.let { service ->
            // Agregar listener para cambios de estado de reproducción
            service.addPlaybackStateListener { playing ->
                isPlaying = playing
                updatePlayPauseButton()
                if (playing) {
                    startProgressUpdates()
                } else {
                    stopProgressUpdates()
                }
            }

            // Agregar listener para cambios de canción
            service.addSongChangeListener { song ->
                currentSong = song
                song?.let { 
                    updateSongInfo(it)
                    loadAlbumArt(it)
                    checkFavoriteStatus(it)
                }
            }
        }
    }

    private fun updateUIFromService() {
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] updateUIFromService: shuffle state = $isShuffleEnabled")
        musicService?.let { service ->
            currentSong = service.getCurrentSong()
            isPlaying = service.isPlaying()

            currentSong?.let { song ->
                updateSongInfo(song)
                loadAlbumArt(song)
                checkFavoriteStatus(song)
            }

            updatePlayPauseButton()
            updateShuffleButton()
            updateRepeatButton()
            updateProgressBar()

            // Solo iniciar actualizaciones si está reproduciéndose
            if (isPlaying) {
                startProgressUpdates()
            }
        }
    }

    private fun updateSongInfo(song: Song) {
        binding.tvSongTitle.text = song.title
        binding.tvArtistName.text = song.artist
        binding.tvPlayingFrom.text = song.album ?: "Unknown Album"
        binding.tvTotalTime.text = formatTime(song.duration?.toLong() ?: 0)

        // Actualizar el máximo del SeekBar
        val duration = song.duration ?: 0
        binding.seekBarProgress.max = 100 // Usamos porcentajes para mejor control
    }

    private fun loadAlbumArt(song: Song) {
        try {
            val (username, token, salt) = musicRepository.getAuthParams()
            val coverUrl = if (song.albumId != null) {
                "${musicRepository.serverUrl}/rest/getCoverArt.view?id=${song.albumId}&u=$username&t=$token&s=$salt&v=1.16.1&c=Castafiore&size=500"
            } else {
                null
            }

            if (coverUrl != null) {
                Glide.with(this)
                    .asBitmap()
                    .load(coverUrl)
                    .placeholder(R.drawable.ic_album_placeholder)
                    .error(R.drawable.ic_album_placeholder)
                    .into(object : CustomTarget<Bitmap>() {
                        override fun onResourceReady(resource: Bitmap, transition: Transition<in Bitmap>?) {
                            binding.ivAlbumCover.setImageBitmap(resource)
                            extractColorsAndApplyTheme(resource)
                        }

                        override fun onLoadCleared(placeholder: Drawable?) {
                            binding.ivAlbumCover.setImageDrawable(placeholder)
                            applyDefaultTheme()
                        }
                    })
            } else {
                binding.ivAlbumCover.setImageResource(R.drawable.ic_album_placeholder)
                applyDefaultTheme()
            }
        } catch (e: Exception) {
            binding.ivAlbumCover.setImageResource(R.drawable.ic_album_placeholder)
            applyDefaultTheme()
        }
    }

    private fun extractColorsAndApplyTheme(bitmap: Bitmap) {
        Palette.from(bitmap).generate { palette ->
            palette?.let {
                val dominantColor = it.getDominantColor(Color.parseColor("#121212"))
                val vibrantColor = it.getVibrantColor(dominantColor)

                // Aplicar color estático por ahora (consistente con el resto de la app)
                applyDefaultTheme()
            } ?: applyDefaultTheme()
        }
    }

    private fun applyDefaultTheme() {
        // Aplicar tema estático consistente
        val staticColor = Color.parseColor("#121212")
        binding.gradientBackground.setBackgroundColor(staticColor)
        StatusBarUtils.setStatusBarColor(this)
    }

    private fun togglePlayPause() {
        musicService?.let { service ->
            if (service.isPlaying()) {
                service.pause()
            } else {
                service.resume()
            }
            // El estado se actualizará automáticamente a través del listener
        }
    }

    private fun playNext() {
        musicService?.next()
    }

    private fun playPrevious() {
        musicService?.previous()
    }

    private fun toggleShuffle() {
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleShuffle: Before toggle = $isShuffleEnabled")
        isShuffleEnabled = !isShuffleEnabled
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleShuffle: After toggle = $isShuffleEnabled")
        updateShuffleButton()

        // Guardar el estado en SharedPreferences
        val prefs = getSharedPreferences("player_prefs", Context.MODE_PRIVATE)
        prefs.edit().putBoolean("shuffle_mode", isShuffleEnabled).apply()
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleShuffle: Saved to SharedPreferences = $isShuffleEnabled")

        if (isShuffleEnabled) {
            musicService?.shuffleQueue()
        } else {
            musicService?.unshuffleQueue()
        }
    }

    private fun toggleRepeat() {
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleRepeat: Before toggle = $repeatMode")
        repeatMode = when (repeatMode) {
            RepeatMode.OFF -> RepeatMode.ALL
            RepeatMode.ALL -> RepeatMode.ONE
            RepeatMode.ONE -> RepeatMode.OFF
        }
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleRepeat: After toggle = $repeatMode")
        updateRepeatButton()

        // Guardar el estado en SharedPreferences
        val prefs = getSharedPreferences("player_prefs", Context.MODE_PRIVATE)
        prefs.edit().putInt("repeat_mode", repeatMode.ordinal).apply()
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleRepeat: Saved to SharedPreferences = $repeatMode")

        // Sincronizar el estado con el servicio
        val serviceRepeatMode = when (repeatMode) {
            RepeatMode.OFF -> MusicService.RepeatMode.OFF
            RepeatMode.ALL -> MusicService.RepeatMode.ALL
            RepeatMode.ONE -> MusicService.RepeatMode.ONE
        }
        musicService?.setRepeatMode(serviceRepeatMode)
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] toggleRepeat: Synced with MusicService = $repeatMode")
    }

    private fun toggleFavorite() {
        currentSong?.let { song ->
            lifecycleScope.launch {
                try {
                    val result = if (isFavorite) {
                        // Si ya es favorito, quitar de favoritos
                        musicRepository.unstarSong(song.id)
                    } else {
                        // Si no es favorito, agregar a favoritos
                        musicRepository.starSong(song.id)
                    }

                    result.fold(
                        onSuccess = {
                            // Actualizar el estado local
                            isFavorite = !isFavorite
                            updateFavoriteButton()

                            val message = if (isFavorite) {
                                "Agregado a favoritos"
                            } else {
                                "Eliminado de favoritos"
                            }
                            showMessage(message)
                        },
                        onFailure = { exception ->
                            showMessage("Error al actualizar favoritos: ${exception.message}")
                        }
                    )
                } catch (e: Exception) {
                    showMessage("Error al actualizar favoritos: ${e.message}")
                }
            }
        }
    }

    private fun checkFavoriteStatus(song: Song) {
        lifecycleScope.launch {
            try {
                val result = musicRepository.isSongStarred(song.id)
                result.fold(
                    onSuccess = { isStarred ->
                        isFavorite = isStarred
                        updateFavoriteButton()
                    },
                    onFailure = {
                        // En caso de error, asumir que no es favorito
                        isFavorite = false
                        updateFavoriteButton()
                    }
                )
            } catch (e: Exception) {
                // En caso de excepción, asumir que no es favorito
                isFavorite = false
                updateFavoriteButton()
            }
        }
    }

    private fun shareCurrentSong() {
        currentSong?.let { song ->
            val shareText = "Escuchando: ${song.title} - ${song.artist}"
            val shareIntent = Intent().apply {
                action = Intent.ACTION_SEND
                type = "text/plain"
                putExtra(Intent.EXTRA_TEXT, shareText)
            }

            val chooser = Intent.createChooser(shareIntent, "Compartir canción")
            startActivity(chooser)
        }
    }

    private fun updatePlayPauseButton() {
        val iconRes = if (isPlaying) R.drawable.ic_pause else R.drawable.ic_play
        binding.btnPlayPause.setImageResource(iconRes)
    }

    private fun updateShuffleButton() {
        android.util.Log.d("PlayerActivity", "[DEBUG_LOG] updateShuffleButton: Using shuffle state = $isShuffleEnabled")
        val tint = if (isShuffleEnabled) {
            getColor(R.color.primary)
        } else {
            getColor(R.color.text_secondary)
        }
        binding.btnShuffle.imageTintList = android.content.res.ColorStateList.valueOf(tint)
    }

    private fun updateRepeatButton() {
        val (iconRes, tint) = when (repeatMode) {
            RepeatMode.OFF -> R.drawable.ic_repeat to getColor(R.color.text_secondary)
            RepeatMode.ALL -> R.drawable.ic_repeat to getColor(R.color.primary)
            RepeatMode.ONE -> R.drawable.ic_repeat_one to getColor(R.color.primary)
        }

        binding.btnRepeat.setImageResource(iconRes)
        binding.btnRepeat.imageTintList = android.content.res.ColorStateList.valueOf(tint)
    }

    private fun updateFavoriteButton() {
        val iconRes = if (isFavorite) R.drawable.ic_favorite else R.drawable.ic_favorite_border
        val tint = if (isFavorite) {
            getColor(R.color.primary)
        } else {
            getColor(R.color.text_secondary)
        }

        binding.btnFavorite.setImageResource(iconRes)
        binding.btnFavorite.imageTintList = android.content.res.ColorStateList.valueOf(tint)
    }

    private fun updateProgressBar() {
        musicService?.let { service ->
            val currentPosition = service.getCurrentPosition()
            val duration = currentSong?.duration?.toLong() ?: 1

            if (duration > 0) {
                val progress = ((currentPosition / 1000) * 100 / duration).toInt()
                binding.seekBarProgress.progress = progress
                binding.tvCurrentTime.text = formatTime(currentPosition / 1000)
            }
        }
    }

    private fun startProgressUpdates() {
        stopProgressUpdates()
        updateProgressRunnable = object : Runnable {
            override fun run() {
                if (isPlaying && isBound) {
                    updateProgressBar()
                    handler.postDelayed(this, 1000)
                }
            }
        }
        updateProgressRunnable?.let { handler.post(it) }
    }

    private fun stopProgressUpdates() {
        updateProgressRunnable?.let {
            handler.removeCallbacks(it)
            updateProgressRunnable = null
        }
    }

    private fun formatTime(seconds: Long): String {
        val minutes = seconds / 60
        val secs = seconds % 60
        return String.format("%d:%02d", minutes, secs)
    }

    private fun showMessage(message: String) {
        android.widget.Toast.makeText(this, message, android.widget.Toast.LENGTH_SHORT).show()
    }

    private fun navigateToAlbum(song: Song) {
        // Verificar que la canción tenga información del álbum
        val albumId = song.albumId
        val albumName = song.album

        if (albumId != null && albumName != null) {
            // Como AlbumDetailFragment usa Navigation Component, necesitamos volver a MainActivity
            // y navegar usando Navigation Component
            val intent = Intent(this, MainActivity::class.java).apply {
                // Agregar flags para limpiar el stack y crear una nueva tarea
                flags = Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP
                // Pasar información del álbum para que MainActivity pueda navegar al fragmento correcto
                putExtra("navigate_to", "album_detail")
                putExtra("album_id", albumId)
                putExtra("album_name", albumName)
                // Agregar información adicional del artista
                putExtra("artist_name", song.artist)
                putExtra("artist_id", song.artistId)
            }
            startActivity(intent)
            finish() // Cerrar PlayerActivity
        } else {
            showMessage("Información del álbum no disponible")
        }
    }

    private fun navigateToArtist(song: Song) {
        // Verificar que la canción tenga información del artista
        val artistId = song.artistId
        val artistName = song.artist

        android.util.Log.d("PlayerActivity", "navigateToArtist called - artistId: $artistId, artistName: $artistName")

        if (artistId != null && artistName != null) {
            // Como ArtistDetailFragment usa Navigation Component, necesitamos volver a MainActivity
            val intent = Intent(this, MainActivity::class.java).apply {
                // Agregar flags para limpiar el stack y crear una nueva tarea
                flags = Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP
                // Pasar información del artista para que MainActivity pueda navegar al fragmento correcto
                putExtra("navigate_to", "artist_detail")
                putExtra("artist_id", artistId)
                putExtra("artist_name", artistName)
            }
            android.util.Log.d("PlayerActivity", "Starting MainActivity with artist_detail navigation")
            startActivity(intent)
            finish() // Cerrar PlayerActivity
        } else {
            showMessage("Información del artista no disponible")
        }
    }

    private fun showSongInfoDialog(song: Song) {
        val dialogBuilder = androidx.appcompat.app.AlertDialog.Builder(this)

        // Crear el layout del diálogo
        val dialogView = layoutInflater.inflate(R.layout.dialog_song_info, null)

        // Referencias a las vistas del diálogo
        val tvTitle = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_title)
        val tvArtist = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_artist)
        val tvAlbum = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_album)
        val tvDuration = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_duration)
        val tvGenre = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_genre)
        val tvYear = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_year)
        val tvBitrate = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_bitrate)
        val tvFormat = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_format)
        val tvFileSize = dialogView.findViewById<android.widget.TextView>(R.id.tv_info_file_size)
        val ivCover = dialogView.findViewById<android.widget.ImageView>(R.id.iv_info_cover)

        // Llenar la información
        tvTitle.text = song.title
        tvArtist.text = song.artist ?: "Artista desconocido"
        tvAlbum.text = song.album ?: "Álbum desconocido"
        tvDuration.text = formatTime(song.duration?.toLong() ?: 0)
        tvGenre.text = song.genre ?: "Género desconocido"
        tvYear.text = song.year?.toString() ?: "Año desconocido"
        tvBitrate.text = if (song.bitRate != null) "${song.bitRate} kbps" else "Bitrate desconocido"
        tvFormat.text = song.suffix?.uppercase() ?: "Formato desconocido"
        tvFileSize.text = if (song.size != null) {
            val sizeInMB = song.size / (1024.0 * 1024.0)
            String.format("%.1f MB", sizeInMB)
        } else {
            "Tamaño desconocido"
        }

        // Cargar la portada del álbum
        try {
            val (username, token, salt) = musicRepository.getAuthParams()
            val coverUrl = if (song.albumId != null) {
                "${musicRepository.serverUrl}/rest/getCoverArt.view?id=${song.albumId}&u=$username&t=$token&s=$salt&v=1.16.1&c=Castafiore&size=300"
            } else {
                null
            }

            if (coverUrl != null) {
                Glide.with(this)
                    .load(coverUrl)
                    .placeholder(R.drawable.ic_album_placeholder)
                    .error(R.drawable.ic_album_placeholder)
                    .into(ivCover)
            } else {
                ivCover.setImageResource(R.drawable.ic_album_placeholder)
            }
        } catch (e: Exception) {
            ivCover.setImageResource(R.drawable.ic_album_placeholder)
        }

        dialogBuilder.setView(dialogView)
            .setTitle("Información de la canción")
            .setPositiveButton("Cerrar") { dialog, _ ->
                dialog.dismiss()
            }
            .create()
            .show()
    }

    override fun onStart() {
        super.onStart()
        if (!isBound) {
            bindMusicService()
        }
    }

    override fun onResume() {
        super.onResume()
        StatusBarUtils.setStatusBarColor(this)

        // Reestablecer modo de pantalla completa
        setupFullScreenMode()

        // Actualizar estado desde el servicio
        if (isBound && musicService != null) {
            updateUIFromService()
        }

        // Reiniciar actualizaciones de progreso
        if (isPlaying) {
            startProgressUpdates()
        }
    }

    override fun onPause() {
        super.onPause()
        stopProgressUpdates()
    }

    override fun onStop() {
        super.onStop()
        stopProgressUpdates()
        unbindMusicService()
    }

    override fun onDestroy() {
        super.onDestroy()
        stopProgressUpdates()
    }
}
